import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, BoxGeometry, Mesh, Color, DirectionalLight, AmbientLight } = ctx.THREE;

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  const group = new Group();

  // Root container for local animations/offsets
  const container = new Group();
  group.add(container);

  // Local lights to bring out the PBR and machined metal look
  const localKeyLight = new DirectionalLight(colors.paper, 1.2);
  localKeyLight.position.set(1.5, 3, 2);
  container.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.8);
  localRimLight.position.set(-2, -2, -1.5);
  container.add(localRimLight);

  // Card geometry: thin machined plate
  const cardGeo = new BoxGeometry(3.0, 2.0, 0.08);

  // High quality PBR material for machined-metal feel
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    metalness: 0.55,
    roughness: 0.5,
    roughnessMap: null,
    metalnessMap: null,
    envMapIntensity: 1.0
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  container.add(cardMesh);

  // Create thin bezel/rim highlighting the accent color
  const rimGeo = new BoxGeometry(3.04, 2.04, 0.04);
  const rimMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    metalness: 0.8,
    roughness: 0.2,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.4
  });
  const rimMesh = new Mesh(rimGeo, rimMat);
  rimMesh.position.z = -0.02;
  container.add(rimMesh);

  // Load image texture
  const imageUrl = config.imageUrl ?? "/prism-mock/home/nodes/feature-card.png";
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading texture: ", err);
    });
  }

  // Handle optional text content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.05); // slightly in front of the card
  container.add(textGroup);

  let textOffsetY = 0.4;
  textItems.forEach((item) => {
    if (!item.text) return;
    const isHero = item.role === 'hero' || item.role === 'headline';
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: isHero ? 0.22 : 0.12,
      color: isHero ? colors.paper : colors.accent,
      align: 'center',
      maxWidthPx: 600
    });
    textObj.position.set(0, textOffsetY, 0);
    textGroup.add(textObj);
    textOffsetY -= 0.3;
  });

  // GSAP Hover and Click Animations
  let hoverTimeline = null;
  let clickTimeline = null;

  const handlePointerOver = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    // Rise-in subtle lift
    hoverTimeline.to(container.position, {
      y: 0.15,
      z: 0.1,
      duration: 0.3,
      ease: "power2.out"
    });
    // Glimmer on the metallic edge
    hoverTimeline.to(rimMesh.scale, {
      x: 1.02,
      y: 1.02,
      duration: 0.3,
      ease: "power2.out"
    }, 0);
  };

  const handlePointerOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(container.position, {
      y: 0,
      z: 0,
      duration: 0.4,
      ease: "power3.out"
    });
    hoverTimeline.to(rimMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.4,
      ease: "power3.out"
    }, 0);
  };

  const handlePointerDown = () => {
    if (clickTimeline) clickTimeline.kill();
    clickTimeline = gsap.timeline();
    // Press down
    clickTimeline.to(container.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: "back.out(1.7)"
    });
  };

  const handlePointerUp = () => {
    if (clickTimeline) clickTimeline.kill();
    clickTimeline = gsap.timeline();
    clickTimeline.to(container.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2,
      ease: "power2.out"
    });
    // Emit navigation or interaction event
    ctx.emit("hub-journal.select", { node: config });
  };

  // Register Event Handlers on Object's userData
  group.userData.handlers = {
    pointerover: handlePointerOver,
    pointerout: handlePointerOut,
    pointerdown: handlePointerDown,
    pointerup: handlePointerUp
  };

  // Apply Cinematic Primitives
  const primitiveResults = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](group, prim.params);
        if (result) primitiveResults.push(result);
      }
    });
  } else {
    // Default fallback to requested scroll parallax if missing from config's primitives
    if (ctx.primitives["parallax-scroll"]) {
      const result = ctx.primitives["parallax-scroll"](group, { intensity: 0.25 });
      if (result) primitiveResults.push(result);
    }
  }

  // Cleanup Loop
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    primitiveResults.forEach((res) => {
      if (typeof res.cleanup === 'function') res.cleanup();
    });
    cardGeo.dispose();
    cardMat.dispose();
    rimGeo.dispose();
    rimMat.dispose();
  };

  return group;
}
